		/// <summary>Parses the whole input as <c>SqlStatement</c>, answering rather than throwing.</summary>
		public static Match<Statement> TryParseStatement(string input)
		{
			var source = input;
			var tokens = Tokenize_DotGram(source);

			var starts  = tokens.Starts;
			var lengths = tokens.Lengths;
			var count   = tokens.Count;

			if (tokens.Stopped >= 0)
			{
				var at = tokens.Stopped;

				Recycle_DotGram(tokens);

				var stopped = at < source.Length ? source[at] : '\0';

				return Match<Statement>.Failed(Outcome.NoMatch, at >= source.Length ? "Expected more input." : "Unexpected character '" + (global::System.Char.IsControl(stopped) || stopped == '\'' || stopped == '\\' ? "\\u" + ((int)stopped).ToString("X4", global::System.Globalization.CultureInfo.InvariantCulture) : stopped.ToString()) + "'.", at, null, null);
			}

			var text    = new global::System.ReadOnlySpan<char>(tokens.Kinds, 0, count);
			var parserWhole = new global::System.ReadOnlyMemory<char>(tokens.Kinds, 0, count);
			var failure = new Failure { Quiet = true };

			var end = RecWhole_DotGram_SqlStatement(text, 0, ref failure, out var recognized, source, starts, lengths, parserWhole);

			if (end < 0)
			{
				failure = new Failure { Unasked = true, Doors = failure.Position };
				end     = RecWhole_DotGram_SqlStatement(text, 0, ref failure, out recognized, source, starts, lengths, parserWhole);
			}

			if (end < 0)
			{
				if (tokens.Cut && failure.Position >= count - 1)
				{
					Recycle_DotGram(tokens);

					return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", source.Length, null, null);
				}

				var starved = failure.OutOfInput == failure.Position + 1 || failure.Position >= text.Length;

				var otherwise = starved
					? "Expected more input."
					: "Input does not match 'SqlStatement'.";

				var at = failure.Position < count ? starts[failure.Position] : source.Length;

				Recycle_DotGram(tokens);

				return Match<Statement>.Failed(starved ? Outcome.Starved : Outcome.NoMatch, otherwise, at, failure.Expected, Handed_DotGram(failure.ExpectedMore));
			}

			if (tokens.Cut && end == count)
			{
				Recycle_DotGram(tokens);

				return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", source.Length, null, null);
			}

			var whole = recognized;
			var over  = end == 0 ? 0 : starts[end - 1] + lengths[end - 1];

			Recycle_DotGram(tokens);

			return Match<Statement>.Success(whole, 0, over);
		}

		/// <summary>Parses the whole input as <c>SqlStatement</c>, answering only whether it is one.</summary>
