			if (end < 0)
			{
				Recycle_DotGram(tokens);

				value = default!;
				return false;
			}

			value = recognized;

			Recycle_DotGram(tokens);

			return true;
		}

		/// <summary>Reads a <c>SqlStatement</c> beginning at <paramref name="at"/>.</summary>
		/// <remarks>
		/// The input is not required to end there: what comes back says where the
		/// reading began and how far it got, so a caller may go on from it. A position
		/// is an offset into the text, and a reading begins at a token, so it begins at the first one at or after it.
		/// </remarks>
		public static Match<Statement> TryParseStatement(string input, int at)
		{
			if (at < 0 || at > input.Length)
			{
				return Match<Statement>.Failed(Outcome.NoMatch, "Position " + at.ToString() + " is outside the input.", at, null, null);
			}

			var source = input;
			var tokens = Tokenized_DotGram(source);

			var starts  = tokens.Starts;
			var lengths = tokens.Lengths;
			var count   = tokens.Count;

			var from = TokenAt_DotGram_Sql(starts, count, at);

			if (from < 0)
			{

				return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", source.Length, null, null);
			}

			var text    = new global::System.ReadOnlySpan<char>(tokens.Kinds, 0, count);
			var parserWhole = new global::System.ReadOnlyMemory<char>(tokens.Kinds, 0, count);
			var failure = new Failure { Quiet = true };

			var end = Rec_DotGram_SqlStatement(text, from, ref failure, out var recognized, source, starts, lengths, parserWhole);

			if (end < 0)
			{
				failure = new Failure { Unasked = true, Doors = failure.Position };
				end     = Rec_DotGram_SqlStatement(text, from, ref failure, out recognized, source, starts, lengths, parserWhole);
			}

			var began = starts[from];

			if (end < 0)
			{
				if (failure.Position < from)
					failure.Position = from;

				if (tokens.Cut && failure.Position >= count - 1)
				{

					return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", source.Length, null, null);
				}

				var starved = failure.OutOfInput == failure.Position + 1 || failure.Position >= text.Length;

				var otherwise = starved
					? "Expected more input."
					: "Input does not match 'SqlStatement'.";

				var halted = failure.Position < count ? starts[failure.Position] : source.Length;


				return Match<Statement>.Failed(starved ? Outcome.Starved : Outcome.NoMatch, otherwise, halted, failure.Expected, Handed_DotGram(failure.ExpectedMore));
			}

			if (tokens.Cut && end == count)
			{

				return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", source.Length, null, null);
			}

			var whole = recognized;
			var over  = end == from ? began : starts[end - 1] + lengths[end - 1];


			return Match<Statement>.Success(whole, began, over - began);
		}

		/// <summary>Reads a <c>SqlStatement</c> at <paramref name="at"/>, answering only whether one is there.</summary>
		/// <remarks>
		/// Nothing is said about a refusal: <c>TryParseStatement</c> returning a match says where and why.
		/// On a reading, <paramref name="at"/> moves to the end of what was read; on a
		/// refusal it stays where it was.
		/// </remarks>
		public static bool TryParseStatement(string input, ref int at, out Statement value)
		{
			if (at < 0 || at > input.Length)
				throw new global::System.ArgumentOutOfRangeException(nameof(at));

			var source = input;
			var tokens = Tokenized_DotGram(source);

			var starts  = tokens.Starts;
			var lengths = tokens.Lengths;
			var count   = tokens.Count;

			var from = TokenAt_DotGram_Sql(starts, count, at);

			if (from < 0)
			{

				value = default!;
				return false;
			}

			var text    = new global::System.ReadOnlySpan<char>(tokens.Kinds, 0, count);
			var parserWhole = new global::System.ReadOnlyMemory<char>(tokens.Kinds, 0, count);
			var failure = new Failure { Quiet = true };

			var end = Rec_DotGram_SqlStatement(text, from, ref failure, out var recognized, source, starts, lengths, parserWhole);

			if (end < 0 || (tokens.Cut && end == count))
			{

				value = default!;
				return false;
			}

			var began = starts[from];

			value = recognized;
			at = end == from ? began : starts[end - 1] + lengths[end - 1];


			return true;
		}

		/// <summary>Reads a <c>SqlStatement</c> inside a window of the input.</summary>
