				}

				var starved = failure.OutOfInput == failure.Position + 1 || failure.Position >= text.Length;

				var otherwise = starved
					? "Expected more input."
					: "Input does not match 'SqlStatement'.";

				var halted = failure.Position < count ? starts[failure.Position] : at + length;

				Recycle_DotGram(tokens);

				return Match<Statement>.Failed(starved ? Outcome.Starved : Outcome.NoMatch, otherwise, halted, failure.Expected, Handed_DotGram(failure.ExpectedMore));
			}

			if (tokens.Cut && end == count)
			{
				Recycle_DotGram(tokens);

				return Match<Statement>.Failed(Outcome.Starved, "Expected more input.", at + length, null, null);
			}

			var whole = recognized;
			var over  = end == 0 ? began : starts[end - 1] + lengths[end - 1];

			Recycle_DotGram(tokens);

			return Match<Statement>.Success(whole, began, over - began);
