			void Kept(int pos, int word, ulong bit, int cell, int end, object? value, bool built)
			{
				var at = (pos - memoAt) * 1 + word;

				if ((uint)at < (uint)memo.Length)
				{
					memo[at] |= bit;

					if (at >= ways.MemoUsed)
						ways.MemoUsed = at + 1;

					var keptAt = cell * keptRun + (pos - memoAt) * 2;

					kept[keptAt]     = end;
					kept[keptAt + 1] = !built ? -2 : value == null ? -1 : ways.Keep(value);
				}
			}

			void MemoFailed(int pos, int word, ulong bit)
			{
				// Nothing a look refuses is recorded; a reading outside it that met the bit would record
				// nothing either, and what was expected there would go unsaid.
				if (failure.Looking > 0)
					return;

				var at = (pos - memoAt) * 1 + word;

				if ((uint)at < (uint)memo.Length)
				{
					memo[at] |= bit;

					if (at >= ways.MemoUsed)
						ways.MemoUsed = at + 1;
				}
			}

