			static int TokenAt_DotGram_Value(int[] starts, int count, int at)
			{
				var low  = 0;
				var high = count - 1;

				while (low <= high)
				{
					var middle = low + ((high - low) >> 1);
					var began  = starts[middle];

					if (began == at)
						return middle;

					if (began < at)
