			static int TokenAt_DotGram_ValueExpressionTree(int[] starts, int count, int at)
			{
				var low  = 0;
				var high = count - 1;

				while (low <= high)
				{
					var middle = low + ((high - low) >> 1);
					var began  = starts[middle];

					if (began == at)
						return middle;

					if (began < at)
						low = middle + 1;
					else
						high = middle - 1;
				}

				// Where none begins there, the first one after it: `low` is where the search
				// ended, and the count where nothing is left to read.
				return low < count ? low : -1;
			}

			static string Text_DotGram_ValueExpressionTree(string source, int[] starts, int[] lengths, int from, int length)
			{
				if (length <= 0)
					return string.Empty;

				var began = starts[from];
				var ended = starts[from + length - 1] + lengths[from + length - 1];

				if (ended - began == 1 && source[began] < 128)
				{
					var one = source[began];

					return Letters_DotGram_ValueExpressionTree[one] ??= source.Substring(began, 1);
				}

				return source.Substring(began, ended - began);
			}

