		internal static int Scan(global::System.ReadOnlySpan<char> text, int pos, out int kind)
		{
			var state = 0;
			var end   = pos;
			var found = 0;
			var p     = pos;

			while (p < text.Length)
			{
				var c    = text[p];
				var row  = Lex_DotGram_States[state];
				var at   = c - (int)(row >> 32);
				int next;

				if ((uint)at < 128u)
					next = Lex_DotGram_Cells[(int)row + Lex_DotGram_Class[at]];
				else
				{
					next =
						state <= 1573 ? Lex_DotGram_Part0(state, c) :
						Lex_DotGram_Part1(state, c);
				}

				if (next < 0)
					goto Done;

				var again = next == state;

				state = next;
				p++;

				// A run of one class, which the row above already decided.
				if (again)
				{
					var over = Lex_DotGram_Runs[state] << 8;

					while (p < text.Length)
					{
						var ahead = text[p];

						if (ahead > 255 || Lex_DotGram_Running[over + ahead] == 0)
							break;

						p++;
					}
				}

				var accepts = Lex_DotGram_Accepts[state];

				if (accepts != 0)
					(end, found) = (p, accepts);
			}

			Done:
			kind = found;

			return end;
		}

		static bool Lex_DotGram_RunsOut(global::System.ReadOnlySpan<char> text, int pos)
		{
			var state = 0;

			for (var p = pos; p < text.Length; p++)
			{
				var c    = text[p];
				var row  = Lex_DotGram_States[state];
				var at   = c - (int)(row >> 32);
				int next;

				if ((uint)at < 128u)
					next = Lex_DotGram_Cells[(int)row + Lex_DotGram_Class[at]];
				else
				{
					next =
						state <= 1573 ? Lex_DotGram_Part0(state, c) :
						Lex_DotGram_Part1(state, c);
				}

				if (next < 0)
					return false;

				state = next;
			}

			return true;
		}

